// Dispatchers.Main para UI (implicito no viewModelScope)

class FeedViewModel(private val repo: FeedRepo) : ViewModel() {
    fun refresh() = viewModelScope.launch {
        try {
            val posts = repo.fetch()
            _state.update { it.copy(posts = posts) }
        } catch (e: CancellationException) { throw e }
          catch (e: Exception) { _state.update { it.copy(error = e.message) } }
    }
}

@Composable
fun FeedScreen(vm: FeedViewModel) {
    // No Compose, collectAsStateWithLifecycle usa repeatOnLifecycle internamente
    val ui by vm.state.collectAsStateWithLifecycle()
    FeedContent(ui)
}

suspend fun loadDashboard(userId: Long) = coroutineScope {
    val profile = async { repo.profile(userId) }
    val feed    = async { repo.feed(userId) }
    val stats   = async { repo.stats(userId) }
    Dashboard(
        profile = profile.await(),
        feed    = feed.await(),
        stats   = stats.await(),
    )
    // se qualquer async falhar, os outros sao cancelados e a funcao lanca
}

// supervisorScope quando quer que falhas isoladas NAO cancelem irmaos
suspend fun loadWithFallback(userId: Long) = supervisorScope {
    val profile = async { repo.profile(userId) }
    val notifs  = async { runCatching { repo.notifs(userId) }.getOrDefault(emptyList()) }
    profile.await() to notifs.await()
}

fun observeUsers(): Flow<List<User>> = flow {
    while (true) {
        val list = api.users()
        emit(list)
        delay(30_000)
    }
}.flowOn(Dispatchers.IO)
   .distinctUntilChanged()
   .catch { e -> emit(emptyList()) }

// Uso:
viewModelScope.launch {
    observeUsers().collect { list ->
        _state.update { it.copy(users = list) }
    }
}

data class UiState(
    val loading: Boolean = false,
    val items: List<Item> = emptyList(),
    val error: String? = null,
)

class ItemsViewModel(repo: ItemsRepo) : ViewModel() {
    val state: StateFlow<UiState> = repo.observeAll()
        .map { UiState(loading = false, items = it) }
        .onStart { emit(UiState(loading = true)) }
        .catch { emit(UiState(error = it.message)) }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.WhileSubscribed(5_000),
            initialValue = UiState(loading = true),
        )
}

sealed interface UiEvent {
    data class Toast(val message: String) : UiEvent
    data object NavigateBack : UiEvent
}

class CheckoutViewModel : ViewModel() {
    private val _events = MutableSharedFlow<UiEvent>()
    val events: SharedFlow<UiEvent> = _events.asSharedFlow()

    fun pagar() = viewModelScope.launch {
        runCatching { gateway.charge() }
            .onSuccess { _events.emit(UiEvent.NavigateBack) }
            .onFailure { _events.emit(UiEvent.Toast("Pagamento falhou: ${it.message}")) }
    }
}

@Composable
fun CheckoutScreen(vm: CheckoutViewModel) {
    val ctx = LocalContext.current
    LaunchedEffect(Unit) {
        vm.events.collect { event ->
            when (event) {
                is UiEvent.Toast -> Toast.makeText(ctx, event.message, Toast.LENGTH_SHORT).show()
                UiEvent.NavigateBack -> { /* navController.popBackStack() */ }
            }
        }
    }
    // ... UI
}

